function fdScope(css,id){let o='',i=0;while(i<css.length){const j=css.indexOf('{',i);if(j<0)break;const sel=css.slice(i,j).trim();let d=1,k=j+1;while(k<css.length&&d){if(css[k]==='{')d++;else if(css[k]==='}')d--;k++}const body=css.slice(j+1,k-1);if(sel[0]==='@')o+=sel+'{'+body+'}\n';else o+=sel.split(',').map(x=>`html[data-xt=${id}] ${x.trim()}`).join(',')+'{'+body+'}\n';i=k}return o}
